<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\Advisory;use App\Models\EmergencyHotline;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Notifications\DatabaseNotification;
class AdminContentController extends Controller {
 public function advisories(){return view('admin.content.advisories',['items'=>Advisory::latest()->paginate(15)]);}
 public function storeAdvisory(Request $r){$d=$r->validate(['title'=>'required|string|max:255','type'=>'required|in:announcement,advisory','summary'=>'required|string|max:500','content'=>'required|string|max:20000','audience'=>'required|in:residents,staff,everyone','status'=>'required|in:draft,published,archived','is_urgent'=>'nullable|boolean','expires_at'=>'nullable|date|after:now']);$item=Advisory::create([...$d,'is_urgent'=>$r->boolean('is_urgent'),'published_at'=>$d['status']==='published'?now():null,'created_by'=>$r->user()->id]);if($item->status==='published')$this->notifyAudience($item);return back()->with('success','Advisory saved.');}
 public function updateAdvisory(Request $r,Advisory $advisory){$d=$r->validate(['title'=>'required|string|max:255','type'=>'required|in:announcement,advisory','summary'=>'required|string|max:500','content'=>'required|string|max:20000','audience'=>'required|in:residents,staff,everyone','status'=>'required|in:draft,published,archived','is_urgent'=>'nullable|boolean','expires_at'=>'nullable|date']);$advisory->update([...$d,'is_urgent'=>$r->boolean('is_urgent'),'published_at'=>$d['status']==='published'?($advisory->published_at?:now()):null]);return back()->with('success','Advisory updated.');}
 public function deleteAdvisory(Advisory $advisory){$advisory->delete();return back()->with('success','Advisory archived.');}
 public function hotlines(){return view('admin.content.hotlines',['items'=>EmergencyHotline::orderBy('sort_order')->paginate(20)]);}
 public function createHotline(){return view('admin.content.hotlines-create');}
 public function storeHotline(Request $r){EmergencyHotline::create($this->hotlineData($r));return back()->with('success','Emergency hotline saved.');}
 public function updateHotline(Request $r,EmergencyHotline $hotline){$hotline->update($this->hotlineData($r));return back()->with('success','Emergency hotline updated.');}
 public function deleteHotline(EmergencyHotline $hotline){$hotline->delete();return back()->with('success','Emergency hotline removed.');}
 private function hotlineData(Request $r):array{$d=$r->validate(['group'=>'required|string|max:100','organization'=>'required|string|max:255','icon_type'=>'required|in:emergency,police,fire,ambulance,hospital,rescue,disaster,women,traffic,utility,barangay,other','hotline'=>'required|string|max:100','alternative_number'=>'nullable|string|max:100','contact_person'=>'nullable|string|max:255','availability_type'=>'required|in:24_7,custom','address'=>'nullable|string|max:500','coverage_area'=>'required|string|max:255','hours'=>'nullable|string|max:255','description'=>'required|string|max:2000','status'=>'required|in:active,temporarily_unavailable,inactive','priority'=>'required|in:high,normal,low','last_verified_at'=>'nullable|date','verified_by'=>'nullable|exists:users,id','sort_order'=>'nullable|integer|min:0|max:999','is_active'=>'nullable|boolean','show_in_resident_app'=>'nullable|boolean']);$d['hours']=$d['availability_type']==='24_7'?'24/7':($d['hours']??'');$d['is_active']=$d['status']==='active';$d['show_in_resident_app']=$r->boolean('show_in_resident_app');$d['verified_by']=$r->filled('last_verified_at')?$r->user()->id:null;return $d;}
 private function notifyAudience(Advisory $item):void {$roles=$item->audience==='everyone'?['resident','staff']:[$item->audience==='residents'?'resident':'staff'];User::whereIn('role',$roles)->where('status','active')->each(function($user)use($item){$user->notifications()->create(['id'=>(string)str()->uuid(),'type'=>'advisory.published','data'=>['title'=>$item->title,'message'=>$item->summary,'advisory_id'=>$item->id,'deep_link'=>'bantayfatima://updates/'.$item->id]]);});}
}
